from itertools import combinations
from sklearn.base import BaseEstimator,RegressorMixin
from sklearn.linear_model import Lasso,ElasticNet
from scipy.linalg import lstsq
class PairResidual(BaseEstimator,RegressorMixin):
 def __init__(self,kind='sqdiff',alpha=1,centers='fit'):
  self.kind=kind; self.alpha=alpha; self.centers=centers
 def build(self,x):
  a=(x[nums].values-self.sc.mean_)/self.sc.scale_;ct=self.enc.transform(x[cats[:2]])
  aa=np.column_stack([a,a*a,ct,np.ones(len(x))]);z=(x[nums].values-self.center)/self.scale
  if self.kind=='sqdiff': b=np.column_stack([abs(z[:,i]**2-z[:,j]**2) for i,j in combinations(range(len(nums)),2)])
  if self.kind=='absprod':b=np.column_stack([abs(z[:,i]*z[:,j]) for i,j in combinations(range(len(nums)),2)])
  if self.kind=='absdiff':b=np.column_stack([abs(z[:,i]-z[:,j]) for i,j in combinations(range(len(nums)),2)])
  return aa,b
 def fit(self,x,y):
  self.sc=StandardScaler().fit(x[nums]);self.enc=OneHotEncoder(sparse_output=False,drop='first',handle_unknown='ignore').fit(x[cats[:2]])
  self.center=self.sc.mean_;self.scale=self.sc.scale_
  aa,_=self.build(x);m=Ridge(alpha=.01).fit(aa,y);cf=m.coef_
  peaks=self.sc.mean_-cf[:len(nums)]/(2*cf[len(nums):2*len(nums)])*self.sc.scale_
  self.center=np.minimum(np.maximum(peaks,x[nums].quantile(.15)),x[nums].quantile(.85)) if self.centers=='fit' else self.sc.mean_
  aa,b=self.build(x);self.co=lstsq(aa,b)[0];r=b-aa@self.co;self.bs=StandardScaler().fit(r);self.co0=lstsq(aa,y)[0];e=y-aa@self.co0
  self.lr=Lasso(alpha=self.alpha,max_iter=20000).fit(self.bs.transform(r),e)
  return self
 def predict(self,x):
  aa,b=self.build(x);return aa@self.co0+self.lr.predict(self.bs.transform(b-aa@self.co))
for kind in ['sqdiff','absprod','absdiff']:
 for alpha in [.3,.6,1,2,3]:
  evaluate(kind+'_'+str(alpha),PairResidual(kind,alpha))
 m=PairResidual(kind,1).fit(X,y)
 print('SELECTED',kind,sorted([(nums[i]+'_'+nums[j],round(v,2)) for (i,j),v in zip(combinations(range(len(nums)),2),m.lr.coef_) if abs(v)>.5],key=lambda x:-abs(x[1])),flush=True)
