from sklearn.linear_model import ARDRegression,BayesianRidge,Lasso
from sklearn.base import BaseEstimator,RegressorMixin
from sklearn.model_selection import RepeatedKFold
from sklearn.preprocessing import FunctionTransformer
class Additive(BaseEstimator,RegressorMixin):
 def __init__(self,degree=2,drop=(),reg='ridge',alpha=.1,weakpenalty=1):self.degree=degree;self.drop=drop;self.reg=reg;self.alpha=alpha;self.weakpenalty=weakpenalty
 def transform(self,x):
  a=self.sc.transform(x[self.nn]);ct=self.enc.transform(x[cats[:2]])
  zz=np.column_stack([a**i for i in range(1,self.degree+1)]+[ct]);return zz
 def fit(self,x,y):
  self.nn=[c for c in nums if c not in self.drop];self.sc=StandardScaler().fit(x[self.nn]);self.enc=OneHotEncoder(sparse_output=False,drop='first',handle_unknown='ignore').fit(x[cats[:2]])
  a=self.transform(x);self.sca=StandardScaler().fit(a);a=self.sca.transform(a)
  if self.reg=='ard': self.model=ARDRegression(max_iter=1000)
  if self.reg=='bayes':self.model=BayesianRidge()
  if self.reg=='ridge':self.model=Ridge(alpha=self.alpha)
  if self.reg=='lasso':self.model=Lasso(alpha=self.alpha,max_iter=10000)
  self.model.fit(a,y);return self
 def predict(self,x):return self.model.predict(self.sca.transform(self.transform(x)))
cv=list(RepeatedKFold(n_splits=5,n_repeats=4,random_state=13).split(X))
models={
 'quadratic':Additive(),
 'quadratic_no4':Additive(drop=('Si','Nb','Ti','Cu')),
 'quadratic_no3':Additive(drop=('Si','Nb','Cu')),
 'quadratic_no2':Additive(drop=('Si','Cu')),
 'ard2':Additive(reg='ard'),
 'bayes2':Additive(reg='bayes'),
 'ard3':Additive(reg='ard',degree=3),
 'lasso.3':Additive(reg='lasso',alpha=.3),
 'lasso.6':Additive(reg='lasso',alpha=.6),
 'lasso1':Additive(reg='lasso',alpha=1),
}
for name,m in models.items():
 es=[]
 for ti,vi in cv:
  m.fit(X.iloc[ti],y[ti]);es.extend((y[vi]-m.predict(X.iloc[vi]))**2)
 m.fit(X,y);p=m.predict(P)
 print(name,'RMSE',round(np.mean(es)**.5,3),flush=True);print(pd.DataFrame({'id':pool.candidate_id,'p':p}).nlargest(8,'p').round(2).to_string(index=False),flush=True)
 if name=='quadratic':
  import statsmodels.api as sm
  aa=m.sca.transform(m.transform(X));smr=sm.OLS(y,sm.add_constant(aa)).fit();print(smr.summary(xname=['const']+[c+'_'+str(i) for i in range(1,3) for c in m.nn]+list(m.enc.get_feature_names_out())))

